const today = () => new Date().toISOString().slice(0, 10);
const titleCase = (value: string) => value.replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
const addDays = (date: string, days: number) => { const value = new Date(`${date.slice(0, 10)}T00:00:00Z`); value.setUTCDate(value.getUTCDate() + days); return value.toISOString().slice(0, 10); };
const formatDate = (date: string) => new Intl.DateTimeFormat("en-PH", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" }).format(new Date(date));
const nextHealthAction = (log: HealthLog) => {
  const dates = [
    { label: "Follow-up", date: log.follow_up_date },
    { label: "Next due", date: log.next_due_date },
    { label: "Withdrawal ends", date: log.withdrawal_end_date },
  ].filter((item): item is { label: string; date: string } => Boolean(item.date));
  const current = today();
  return dates.filter((item) => item.date >= current).sort((a, b) => a.date.localeCompare(b.date))[0]
    ?? dates.sort((a, b) => b.date.localeCompare(a.date))[0];
};
const healthEmpty = { record_type: "checkup", record_date: today(), diagnosis: "", details: "", treatment: "", medication_name: "", dose: "", administration_route: "", treatment_start_date: "", treatment_end_date: "", withdrawal_end_date: "", next_due_date: "", veterinarian: "", follow_up_date: "", status: "open" };
const weightEmpty = { measured_at: today(), weight_kg: "", notes: "", recorded_by: "" };
