function Field({ label, name, value, type = "text", required = false, options }: { label: string; name: string; value: string; type?: string; required?: boolean; options?: string[] }) {
  const onChange = useContext(FieldChangeContext);
  return <label className="field">{label}{options ? <select required={required} value={value} onChange={(event) => onChange(name, event.target.value)}>{options.map((option) => <option key={option} value={option}>{option || "Select"}</option>)}</select> : <input required={required} type={type} step={type === "number" ? "0.01" : undefined} min={type === "number" ? "0.01" : undefined} value={value} onChange={(event) => onChange(name, event.target.value)}/>}</label>;
}

function Fact({ label, field, suffix = "", wide = false }: { label: string; field: string; suffix?: string; wide?: boolean }) {
  const animal = useContext(AnimalContext);
  const value = animal?.[field];
  const display = value === true ? "Yes" : value === false ? "No" : value == null || value === "" ? "-" : `${String(value).slice(0, field.endsWith("date") ? 10 : undefined)}${suffix}`;
  return <div className={wide ? "profile-fact-wide" : undefined}><dt>{label}</dt><dd>{field === "purchase_price" && value ? new Intl.NumberFormat("en-PH", { style: "currency", currency: "PHP" }).format(Number(value)) : display}</dd></div>;
}

function CurrentPregnancyTable({ animal, pregnancy }: { animal: Animal; pregnancy: PregnancyData }) {
  if (!pregnancy.pregnancy) return null;
  const current = pregnancy.pregnancy;
  const progress = Math.min(100, Math.round(current.days_pregnant / 283 * 100));
      return <section className="panel breeding-workspace" aria-labelledby="profile-current-pregnancy-title"><div className="section-heading"><div><h2 id="profile-current-pregnancy-title">Current Pregnancy Status</h2><span className="cattle-eyebrow">Cattle ID</span><p>Confirmed pregnancy for this cattle profile.</p></div></div><div className="pregnancy-table-shell"><table className="pregnancy-workspace-table"><thead><tr><th>Dam</th><th>Pregnancy stage</th><th>Gestation</th><th>Expected calving</th><th>Next care</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody><tr><td data-label="Dam"><strong>{animal.tag_number}</strong><span>{animal.name || animal.breed}</span></td><td data-label="Pregnancy stage"><span className={`pregnancy-stage pregnancy-stage-${current.key}`}>{current.label}</span></td><td data-label="Gestation"><strong>Day {current.days_pregnant}</strong><progress max="283" value={Math.min(current.days_pregnant, 283)} aria-label={`${animal.tag_number} gestation progress`}/><small>{progress}% of ~283 days</small></td><td data-label="Expected calving"><time dateTime={current.expected_calving_date}>{current.expected_calving_date.slice(0, 10)}</time></td><td data-label="Next care">{current.guidance}</td><td data-label="Actions"><Link className="pregnancy-table-open" href={`/pregnancy/${current.confirmation_id}?returnTo=${encodeURIComponent(`/livestock/${animal.id}?tab=pregnancy`)}`}>Open profile</Link></td></tr></tbody></table></div></section>;
}

function PregnancyHistoryTable({ animal, pregnancy }: { animal: Animal; pregnancy: Partial<PregnancyData> | null }) {
  const records = pregnancy?.records?.filter((record) => ["pregnancy_confirmed", "pregnancy_negative", "pregnancy_loss"].includes(record.event_type)) ?? [];
  const history = records.length || !pregnancy?.completed_calving ? records : [{ id: pregnancy.completed_calving.pregnancy_confirmation_id ?? 0, event_type: "pregnancy_confirmed", event_date: pregnancy.completed_calving.birth_date, pregnancy_status: "pregnant", details: "Pregnancy completed by recorded calving.", performed_by: null }];
  return <section className="panel pregnancy-history-panel" aria-labelledby="profile-pregnancy-history-title"><div className="section-heading"><div><span className="cattle-eyebrow">Pregnancy history</span><h2 id="profile-pregnancy-history-title">Pregnancy history</h2><p>Pregnancy records for {animal.tag_number}.</p></div><span className="section-count">{history.length}</span></div>{history.length ? <div className="pregnancy-table-shell"><table className="pregnancy-workspace-table"><thead><tr><th>Cattle ID</th><th>Confirmed</th><th>Expected calving</th><th>Outcome</th><th>Action</th></tr></thead><tbody>{history.map((record) => { const outcome = record.calving_date ? "Delivery successful" : record.event_type === "pregnancy_confirmed" ? "Pregnant" : record.event_type === "pregnancy_loss" ? "Pregnancy loss" : "Not pregnant"; const expectedCalving = record.expected_calving_date || pregnancy?.pregnancy?.expected_calving_date; return <tr key={record.id}><td data-label="Cattle ID"><strong>{animal.tag_number}</strong><span>{animal.name || animal.breed}</span></td><td data-label="Confirmed"><time dateTime={record.event_date}>{formatDate(record.event_date)}</time></td><td data-label="Expected calving">{expectedCalving ? formatDate(expectedCalving) : "Not recorded"}</td><td data-label="Outcome"><span className={`pregnancy-stage pregnancy-stage-${record.event_type}`}>{outcome}</span></td><td data-label="Action">{record.event_type === "pregnancy_confirmed" && record.id > 0 && <Link className="pregnancy-table-open" href={`/pregnancy/${record.id}?returnTo=${encodeURIComponent(`/livestock/${animal.id}?tab=pregnancy`)}`}>View Details</Link>}</td></tr>; })}</tbody></table></div> : <p className="muted">No pregnancy history recorded yet.</p>}</section>;
}

function CalvingHistoryTable({ animal, history }: { animal: Animal; history: CalvingHistory[] }) {
  return <section className="panel pregnancy-history-panel" aria-labelledby="profile-calving-history-title"><div className="section-heading"><div><span className="cattle-eyebrow">Calving history</span><h2 id="profile-calving-history-title">Calving and care history</h2><p>Completed calving records for {animal.tag_number}.</p></div><span className="section-count">{history.length}</span></div>{history.length?<div className="pregnancy-table-shell"><table className="pregnancy-workspace-table"><thead><tr><th>Calving date</th><th>Calf outcome</th><th>Difficulty</th><th>Notes</th><th><span className="sr-only">Action</span></th></tr></thead><tbody>{history.map(item=><tr key={item.id}><td data-label="Calving date"><time dateTime={item.birth_date}>{formatDate(item.birth_date)}</time></td><td data-label="Calf outcome"><strong>{item.calf_count} {item.calf_count===1?"calf":"calves"}</strong><span>{item.calves||"Outcome not recorded"}</span></td><td data-label="Difficulty"><span className={`calving-difficulty calving-difficulty-${item.calving_difficulty}`}>{titleCase(item.calving_difficulty)}</span></td><td data-label="Notes">{item.notes||"Not recorded"}</td><td data-label="Action"><Link className="pregnancy-table-open" href={`/pregnancy/${item.pregnancy_id}?returnTo=${encodeURIComponent(`/livestock/${animal.id}?tab=pregnancy`)}`}>View Details</Link></td></tr>)}</tbody></table></div>:<p className="muted">No calving history recorded yet.</p>}</section>;
}

function ReproductiveProfile({ animal, pregnancy, subtab }: { animal: Animal; pregnancy: Partial<PregnancyData> | null; subtab: "breeding" | "pregnancy" | "calving" }) {
  const female = animal.sex.toLowerCase() === "female";
  return <div className="reproductive-profile">
    {subtab === "pregnancy" && female && <PregnancyHistoryTable animal={animal} pregnancy={pregnancy}/>} 
  </div>;
}

