  async function save(event?: FormEvent, confirmed = false) { event?.preventDefault(); if (!action || !id) return; if (action === "heat" && !confirmed) { setHeatConfirmOpen(true); return; } const savedAction = action; setHeatConfirmOpen(false); setSaving(true); setError(""); const endpoint = action === "health" ? "/api/health" : `/api/livestock/${id}/${action === "weight" ? "weights" : "breeding"}`; const payload = action === "health" ? { ...healthForm, livestock_id: id } : action === "weight" ? weightForm : breedingForm; try { const response = await fetch(endpoint, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); const body = await response.json(); if (!response.ok) throw new Error(body.error ?? "Save failed"); await load(id); setAction(null); setHealthForm({ ...healthEmpty, record_date: today() }); setWeightForm({ ...weightEmpty, measured_at: today() }); setBreedingForm({ ...breedingEmpty, event_date: today() }); setSuccess(savedAction === "health" ? "Health record added successfully." : savedAction === "weight" ? "Weight recorded successfully." : savedAction === "heat" ? "Heat observation recorded successfully." : "Breeding event recorded successfully."); } catch (cause) { setError(cause instanceof Error ? cause.message : "Save failed"); } finally { setSaving(false); } }
