    async function saveLifecycle(event: FormEvent) { event.preventDefault(); setSaving(true); setError(""); try { const response = await fetch(`/api/livestock/${id}`, { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: lifecycleAction, ...lifecycleForm }) }); if (!response.ok) { const body = await response.json(); throw new Error(body.error ?? "Lifecycle update failed"); } setLifecycleOpen(false); if (lifecycleAction === "archive") router.push("/livestock"); else { await load(id); setSuccess(`${animal?.tag_number ?? "Cattle"} marked ${lifecycleAction.replaceAll("_", " ")}. Profile and history retained.`); } } catch (cause) { setError(cause instanceof Error ? cause.message : "Lifecycle update failed"); } finally { setSaving(false); } }
  async function updateHealthStatus(log: HealthLog) { setUpdatingHealthId(log.id); setError(""); try { const response = await fetch(`/api/health/${log.id}`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ status: log.status === "open" ? "resolved" : "open" }) }); const body = await response.json(); if (!response.ok) throw new Error(body.error ?? "Status update failed"); await load(id); setSuccess(log.status === "open" ? "Health record marked resolved." : "Health record reopened."); } catch (cause) { setError(cause instanceof Error ? cause.message : "Status update failed"); } finally { setUpdatingHealthId(null); } }
