    async function saveCheckup(event: FormEvent) { event.preventDefault(); if (!checkupLog || !id) return; if (!checkupForm.notes.trim()) return setError("Checkup notes are required"); if (checkupForm.outcome === "monitoring" && (!checkupForm.next_date || checkupForm.next_date <= today())) return setError("Choose a future checkup date"); const outcome = checkupForm.outcome, nextDate = checkupForm.next_date; setSaving(true); setError(""); try { const response = await fetch(`/api/health/${checkupLog.id}/checkup`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ outcome, notes: checkupForm.notes.trim(), next_date: nextDate }) }); const body = await response.json(); if (!response.ok) throw new Error(body.error ?? "Checkup save failed"); await load(id); setCheckupLog(null); setSuccess(outcome === "recovered" ? "Checkup recorded. Cattle marked recovered." : `Checkup recorded. Monitoring continues until ${formatDate(nextDate)}.`); } catch (cause) { setError(cause instanceof Error ? cause.message : "Checkup save failed"); } finally { setSaving(false); } }
  const setFormField = useCallback((name: string, value: string) => { if (action === "health") setHealthForm((form) => ({ ...form, [name]: value })); else if (action === "weight") setWeightForm((form) => ({ ...form, [name]: value })); else setBreedingForm((form) => ({ ...form, [name]: value })); }, [action]);
  if (error && !animal) return <main className="cattle-profile"><button type="button" className="cattle-back" onClick={goBack}><ArrowLeft size={16}/> Back</button><p role="alert" className="cattle-error">{error}</p></main>;
  if (!animal) return <main className="cattle-profile" aria-live="polite"><p className="muted">Loading cattle record...</p></main>;
  const show = (key: string, suffix = "") => { const value = animal[key]; if (value === true) return "Yes"; if (value === false) return "No"; return value == null || value === "" ? "-" : `${String(value).slice(0, key.endsWith("date") ? 10 : undefined)}${suffix}`; };
  const exportData = () => { const rows = [...Object.entries(animal), ...logs.flatMap((row, i) => Object.entries(row).map(([key, value]) => [`health_${i + 1}_${key}`, value])), ...weights.flatMap((row, i) => Object.entries(row).map(([key, value]) => [`weight_${i + 1}_${key}`, value])), ...breeding.flatMap((row, i) => Object.entries(row).map(([key, value]) => [`breeding_${i + 1}_${key}`, value]))]; const csv = rows.map(([key, value]) => `${key},"${String(value ?? "").replaceAll('"', '""')}"`).join("\n"); const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" })); link.download = `${animal.tag_number}-profile.csv`; link.click(); URL.revokeObjectURL(link.href); };
