    <div className="cattle-profile-nav no-print"><button type="button" className="cattle-back" onClick={goBack} data-tooltip="Return to originating page"><ArrowLeft size={16}/> Back</button><div className="cattle-profile-actions"><details className="export-menu"><summary className="secondary-button"><Download size={16}/> Export</summary><div className="export-menu-options"><button type="button" onClick={exportData}><Download size={15}/> Export CSV</button><button type="button" onClick={() => window.print()}><Printer size={15}/> Print</button></div></details><button type="button" className="secondary-button cattle-actions" data-tooltip="Update sale, transfer, death, cull, or archive status" onClick={() => { setError(""); setLifecycleOpen(true); }}>Update Status</button><button type="button" onClick={() => setEditOpen(true)} className="primary-button cattle-add-button" data-tooltip="Update identity and profile details"><Pencil size={16}/> Edit profile</button></div></div>
    {lifecycleOpen && <div className="cattle-modal-backdrop no-print" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && setLifecycleOpen(false)}><section className="cattle-modal compact-modal" role="dialog" aria-modal="true" aria-labelledby="lifecycle-title"><div className="cattle-panel-heading"><div><span className="cattle-eyebrow">{animal.tag_number}</span><h2 id="lifecycle-title">Cattle lifecycle</h2></div><button type="button" className="icon-button" aria-label="Close" onClick={() => setLifecycleOpen(false)}><X size={18}/></button></div><form className="quick-form" onSubmit={saveLifecycle}>{error && <p role="alert" className="cattle-error quick-form-wide">{error}</p>}<p className="muted quick-form-wide">Lifecycle outcomes retain profile and history. Archive only duplicate or incorrect records.</p><label className="field quick-form-wide">Action<select value={lifecycleAction} onChange={(event) => setLifecycleAction(event.target.value as LifecycleAction)}><option value="sold">Sold</option><option value="deceased">Deceased</option><option value="culled">Culled</option><option value="transferred_out">Transferred out</option><option value="archive">Archive duplicate / incorrect record</option></select></label>{lifecycleAction !== "archive" && <label className="field">Relevant date<input required type="date" max={today()} value={lifecycleForm.date} onChange={(event) => setLifecycleForm((form) => ({ ...form, date: event.target.value }))}/></label>}{lifecycleAction === "sold" && <><label className="field">Buyer<input required maxLength={150} value={lifecycleForm.buyer} onChange={(event) => setLifecycleForm((form) => ({ ...form, buyer: event.target.value }))}/></label><label className="field">Sale price<input required type="number" min="0.01" step="0.01" value={lifecycleForm.price} onChange={(event) => setLifecycleForm((form) => ({ ...form, price: event.target.value }))}/></label></>}<label className="field quick-form-wide">Reason<textarea required maxLength={1000} value={lifecycleForm.reason} onChange={(event) => setLifecycleForm((form) => ({ ...form, reason: event.target.value }))}/></label><div className="modal-actions quick-form-wide"><button type="button" className="secondary-button" onClick={() => setLifecycleOpen(false)}>Cancel</button><button className={lifecycleAction === "archive" ? "danger-button" : "primary-button"} disabled={saving}>{saving ? "Saving..." : lifecycleAction === "archive" ? "Archive record" : "Confirm action"}</button></div></form></section></div>}
    {editOpen && cattleActive && <RegistrationForm initialEditId={String(animal.id)} modalOnly onClose={() => { setEditOpen(false); load(id); }}/>} 
