      const actionTiming = nextAction?.date < today() ? "Overdue" : nextAction?.date === today() ? "Today" : null;
      const needsCheckup = log.status === "open" && ["illness", "injury", "treatment", "antibiotics", "anti_inflammatory"].includes(log.record_type);
      return <article key={log.id} className="health-record"><div className="health-record-icon" aria-hidden="true">{log.record_type === "vaccination" ? <ShieldCheck size={17}/> : <Stethoscope size={17}/>}</div><div className="health-record-body"><header className="health-record-header"><div><strong>{log.record_type.replaceAll("_", " ")}</strong><span className={`record-status ${log.status}`}>{log.status}</span></div><time dateTime={log.record_date}>{formatDate(log.record_date)}</time></header>{summary && <p className="health-record-summary">{summary}</p>}{treatment && <p className="health-record-treatment"><strong>Treatment</strong><span>{treatment}</span></p>}<footer className="health-record-footer"><div>{nextAction && <span className={actionTiming === "Overdue" ? "overdue" : undefined}><CalendarClock size={13}/>{actionTiming === "Overdue" ? "Overdue  -  " : actionTiming === "Today" ? "Today  -  " : ""}{nextAction.label} <time dateTime={nextAction.date}>{formatDate(nextAction.date)}</time></span>}{log.veterinarian && <span><UserRound size={13}/> Administered by {log.veterinarian}</span>}<span><UserRound size={13}/> Added by {log.added_by || "Unknown"}</span></div>{needsCheckup ? <button type="button" className="health-status-button" onClick={() => openCheckup(log)}><Stethoscope size={14}/> Record checkup</button> : <button type="button" className="health-status-button" disabled={updatingHealthId === log.id} onClick={() => updateHealthStatus(log)}>{log.status === "open" ? <Check size={14}/> : <RotateCcw size={14}/>} {updatingHealthId === log.id ? "UpdatingÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦" : log.status === "open" ? "Mark resolved" : "Reopen"}</button>}</footer></div></article>;
