    {tab === "health" && <section className="breeding-records profile-health-records"><header><div><h2>Health Records</h2></div><b>{filteredLogs.length} record{filteredLogs.length === 1 ? "" : "s"}</b></header><div className="operations-toolbar"><label className="operations-search"><Search size={15}/><input aria-label="Search clinical history" placeholder="Search diagnosis or treatment" value={healthSearch} onChange={(event) => { setHealthSearch(event.target.value); setHealthPage(1); }}/></label><div className="operations-filters"><select aria-label="Filter care type" value={healthFilter === "vaccination" || healthFilter === "treatment" ? healthFilter : "all"} onChange={(event) => { setHealthFilter(event.target.value as HealthFilter); setHealthPage(1); }}><option value="all">All care types</option><option value="vaccination">Vaccination</option><option value="treatment">Treatment</option></select><select aria-label="Filter status" value={healthFilter === "open" || healthFilter === "resolved" ? healthFilter : "all"} onChange={(event) => { setHealthFilter(event.target.value as HealthFilter); setHealthPage(1); }}><option value="all">All statuses</option><option value="open">Active</option><option value="resolved">Completed</option></select></div><button type="button" className="primary-button no-print" onClick={() => { setHealthForm((form) => ({ ...form, record_type: "checkup" })); setAction("health"); }}><Plus size={16}/> Add health record</button></div>{filteredLogs.length ? <><div className="clinical-history-table" role="region" aria-label={`${animal.tag_number} clinical history`} tabIndex={0}><table><caption className="sr-only">Clinical history for {animal.tag_number}, newest first</caption><thead><tr><th scope="col">Record</th><th scope="col">Administered By</th><th scope="col">Date</th><th scope="col">Status</th><th scope="col">Actions</th></tr></thead><tbody>{pagedHealthLogs.map((log) => <tr key={log.id}><td><span className={`clinical-record-type health-type-${log.record_type}`}>{log.record_type.replaceAll("_", " ")}</span></td><td>{log.veterinarian || log.added_by || "Unknown"}</td><td><time dateTime={log.record_date}>{formatDate(log.record_date)}</time></td><td><span className={`record-status ${log.status}`}>{log.status === "open" ? "Active" : "Completed"}</span></td><td><button type="button" className="health-table-action" onClick={() => setSelectedHealthLog(log)}><Eye size={15}/> View</button></td></tr>)}</tbody></table></div><div className="operations-pagination"><span>Showing {(currentHealthPage - 1) * 10 + 1}-{Math.min(currentHealthPage * 10, filteredLogs.length)} of {filteredLogs.length}</span><div><button type="button" aria-label="Previous page" disabled={currentHealthPage === 1} onClick={() => setHealthPage((page) => Math.max(1, page - 1))}><ChevronLeft size={15}/></button><span>Page {currentHealthPage} of {healthPageCount}</span><button type="button" aria-label="Next page" disabled={currentHealthPage === healthPageCount} onClick={() => setHealthPage((page) => Math.min(healthPageCount, page + 1))}><ChevronRight size={15}/></button></div></div></> : <div className="health-empty"><HeartPulse size={20}/><strong>No matching health records</strong><span>Add first health record for this cattle.</span></div>}</section>}
